    /** EntityScriptTypeByClass, with any other weapon_* as a weapon and anything else as Entity. */
    type EntityScriptType<C extends string> = C extends keyof EntityScriptTypeByClass
        ? EntityScriptTypeByClass[C]
        : C extends `weapon_${string}` ? CSWeaponBase : Entity;

    interface IPointScript {
        FindEntityByClass<C extends EntityClassName | RuntimeClassName | (string & {})>(className: C): EntityScriptType<C> | undefined;
        FindEntitiesByClass<C extends EntityClassName | RuntimeClassName | (string & {})>(className: C): EntityScriptType<C>[];
        EntFireAtName(config: { name: string, input: EntityInputName | (string & {}), value?: InputValue, caller?: Entity, activator?: Entity, delay?: number }): void;
        EntFireAtTarget(config: { target: Entity, input: EntityInputName | (string & {}), value?: InputValue, caller?: Entity, activator?: Entity, delay?: number }): void;
        ConnectOutput(target: Entity, output: EntityOutputName | (string & {}), callback: (inputData: { value?: InputValue, caller?: Entity, activator?: Entity }) => any): number | undefined;
    }
